import{_ as o,o as t,c as a,ao as l}from"./chunks/framework.Cwk1prfm.js";const w=JSON.parse('{"title":"Compatibility","description":"","frontmatter":{},"headers":[],"relativePath":"compatibility/overview.md","filePath":"compatibility/overview.md","lastUpdated":null}'),r={name:"compatibility/overview.md"};function i(d,e,c,n,s,h){return t(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="Compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#Compatibility" aria-label="Permalink to &quot;Compatibility {#Compatibility}&quot;">​</a></h1><p>This section is a <strong>living compatibility reference</strong> for the <code>Flow</code> constructors. For each way of building a flow — from a vector field, a Hamiltonian vector field, a Hamiltonian, a SciML function/problem, or an optimal control problem — a dedicated page lists the supported state types, scalar types, and call styles in a table, <strong>with a minimal, executable example for every supported cell</strong>.</p><p>Two properties keep these pages trustworthy:</p><ul><li><p><strong>Probe-backed.</strong> Each page&#39;s table is generated from a capability probe under <a href="https://github.com/control-toolbox/CTFlows.jl/tree/main/probe" target="_blank" rel="noreferrer"><code>probe/</code></a> that runs every combination against the current source and records what works, what warns, and what fails. The CPU probe is <a href="https://github.com/control-toolbox/CTFlows.jl/blob/main/probe/cpu/probe_cpu.jl" target="_blank" rel="noreferrer"><code>probe/cpu/probe_cpu.jl</code></a>.</p></li><li><p><strong>Executed on build.</strong> Every ✓ / ⚠ example is a Documenter <code>@example</code> block re-run on each documentation build, so a page cannot silently drift from the code.</p></li></ul><p>Scope: the 8 per-constructor pages below cover <strong>CPU</strong>, with every example executed on build. <a href="./gpu">GPU</a> is covered by a separate page, sourced from a dated probe run rather than build-executed — see that page&#39;s note on why.</p><p>This work tracks issue <a href="https://github.com/control-toolbox/CTFlows.jl/issues/343" target="_blank" rel="noreferrer">#343</a>.</p><h2 id="Pages" tabindex="-1">Pages <a class="header-anchor" href="#Pages" aria-label="Permalink to &quot;Pages {#Pages}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Constructor</th><th style="text-align:right;">Builds</th><th style="text-align:right;">Page</th><th style="text-align:right;">Status</th></tr></thead><tbody><tr><td style="text-align:right;"><code>Flow(::VectorField)</code></td><td style="text-align:right;"><a href="/CTFlows.jl/dev/api/flows#CTFlows.Flows.StateFlow"><code>StateFlow</code></a></td><td style="text-align:right;"><a href="./vector_field"><code>Flow(VectorField)</code></a></td><td style="text-align:right;">✅ live</td></tr><tr><td style="text-align:right;"><code>Flow(::HamiltonianVectorField)</code></td><td style="text-align:right;"><a href="/CTFlows.jl/dev/api/flows#CTFlows.Flows.HamiltonianFlow"><code>HamiltonianFlow</code></a></td><td style="text-align:right;"><a href="./hamiltonian_vector_field"><code>Flow(HamiltonianVectorField)</code></a></td><td style="text-align:right;">✅ live</td></tr><tr><td style="text-align:right;"><code>Flow(::Hamiltonian)</code></td><td style="text-align:right;"><a href="/CTFlows.jl/dev/api/flows#CTFlows.Flows.HamiltonianFlow"><code>HamiltonianFlow</code></a></td><td style="text-align:right;"><a href="./hamiltonian"><code>Flow(Hamiltonian)</code></a></td><td style="text-align:right;">✅ live</td></tr><tr><td style="text-align:right;"><code>Flow(::ODEFunction)</code> / <code>Flow(::ODEProblem)</code></td><td style="text-align:right;"><a href="/CTFlows.jl/dev/api/flows#CTFlows.Flows.StateFlow"><code>StateFlow</code></a> / <code>SciMLProblemFlow</code></td><td style="text-align:right;"><a href="./sciml"><code>Flow(SciML)</code></a></td><td style="text-align:right;">✅ live</td></tr><tr><td style="text-align:right;"><code>Flow(ocp)</code> (control-free)</td><td style="text-align:right;"><a href="/CTFlows.jl/dev/api/flows#CTFlows.Flows.OptimalControlFlow"><code>OptimalControlFlow</code></a></td><td style="text-align:right;"><a href="./ocp_free"><code>Flow(ocp)</code></a></td><td style="text-align:right;">✅ live</td></tr><tr><td style="text-align:right;"><code>Flow(ocp, law)</code></td><td style="text-align:right;"><a href="/CTFlows.jl/dev/api/flows#CTFlows.Flows.OptimalControlFlow"><code>OptimalControlFlow</code></a> / <a href="/CTFlows.jl/dev/api/flows#CTFlows.Flows.ControlledFlow"><code>ControlledFlow</code></a></td><td style="text-align:right;"><a href="./ocp_control_laws"><code>Flow(ocp, law)</code></a></td><td style="text-align:right;">✅ live</td></tr><tr><td style="text-align:right;"><code>Flow(h̃, law)</code></td><td style="text-align:right;"><a href="/CTFlows.jl/dev/api/flows#CTFlows.Flows.HamiltonianFlow"><code>HamiltonianFlow</code></a></td><td style="text-align:right;"><a href="./pseudo_hamiltonian"><code>Flow(h̃, law)</code></a></td><td style="text-align:right;">✅ live</td></tr><tr><td style="text-align:right;"><code>Flow(fc, law)</code></td><td style="text-align:right;"><a href="/CTFlows.jl/dev/api/flows#CTFlows.Flows.ControlledFlow"><code>ControlledFlow</code></a></td><td style="text-align:right;"><a href="./controlled_vector_field"><code>Flow(fc, law)</code></a></td><td style="text-align:right;">✅ live</td></tr><tr><td style="text-align:right;"><em>(all of the above, on GPU)</em></td><td style="text-align:right;">—</td><td style="text-align:right;"><a href="./gpu">GPU</a></td><td style="text-align:right;">✅ live (probe-sourced, not build-executed)</td></tr></tbody></table><h2 id="At-a-glance" tabindex="-1">At a glance <a class="header-anchor" href="#At-a-glance" aria-label="Permalink to &quot;At a glance {#At-a-glance}&quot;">​</a></h2><ul><li><p><a href="./vector_field"><code>Flow(VectorField)</code></a> and <a href="./hamiltonian_vector_field"><code>Flow(HamiltonianVectorField)</code></a> report the same result on CPU: <strong>every</strong> state/costate type tested works — scalar, <code>Vector</code>, <code>Matrix</code> (batched columns), <code>MVector</code> / <code>SVector</code>, <code>MMatrix</code> / <code>SMatrix</code>, with <code>Real</code>, <code>Complex</code>, or <code>ForwardDiff.Dual</code> elements — in both the point and trajectory call styles. The only caveat in both cases is that an <strong>in-place</strong> vector field with an <strong>immutable</strong> initial condition (<code>SVector</code> / <code>SMatrix</code>) works but emits a performance warning. <code>Flow(HamiltonianVectorField)</code> is also already <a href="https://github.com/control-toolbox/Handbook/blob/main/philosophy/dimension-and-shape.md" target="_blank" rel="noreferrer">&quot;1-D = scalar&quot;</a> end to end (point <em>and</em> trajectory), unlike <code>Flow(VectorField)</code> — see <a href="https://github.com/control-toolbox/CTFlows.jl/issues/357" target="_blank" rel="noreferrer">#357</a>.</p></li><li><p><a href="./hamiltonian"><code>Flow(Hamiltonian)</code></a> (AD-backed, no in-place variant) supports every <strong>real</strong> container the same way, but its default backend (<code>AutoForwardDiff</code>) does <strong>not</strong> support <code>Complex</code> states. To differentiate the flow itself with respect to <code>(x0, p0)</code> (e.g. for shooting), wrap the <em>call</em> in an outer <code>ForwardDiff.jacobian</code>/<code>gradient</code> — never construct a <code>Dual</code> by hand and pass it as <code>x0</code>/<code>p0</code>. It is also already 1-D = scalar end to end, via the same coercion machinery as <code>Flow(HamiltonianVectorField)</code> (see #357).</p></li><li><p><a href="./sciml"><code>Flow(SciML)</code></a> covers two constructors with very different mechanics. <code>Flow(::ODEFunction)</code> goes through the same CTFlows pipeline as <code>Flow(VectorField)</code> and reports the identical result (every container works; in-place + immutable state warns and falls back). <code>Flow(::ODEProblem)</code> bypasses that pipeline entirely — <code>SciMLBase.remake</code> feeds the new state straight to the original function, with <strong>no CTFlows-level guard</strong>. For a problem built from an <strong>out-of-place</strong> function, every state type remakes cleanly; for one built <strong>in-place</strong>, remaking with an <strong>immutable</strong> state (including a bare scalar) is a <strong>hard, native SciML error</strong> — not a warning with a fallback like everywhere else on this site. Build the <code>ODEProblem</code> from an out-of-place function if you need to call it with immutable states.</p></li><li><p><a href="./ocp_free"><code>Flow(ocp)</code></a> and <a href="./ocp_control_laws"><code>Flow(ocp, law)</code></a> are the most restricted constructors on this site — unlike every flow above, <strong>the state dimension is fixed at OCP construction</strong> (<code>state!(pre, n)</code>), so no single flow accepts every container size. Two structural causes explain almost every ✗ measured on both pages: (1) the internal derivative buffer is always a fixed-size <code>Vector</code>, which breaks batched <code>Matrix</code> states everywhere, and breaks <code>SVector</code> states specifically on the non-AD (state-only / <code>OpenLoop</code>/<code>ClosedLoop</code>) paths, where OrdinaryDiffEq&#39;s out-of-place solver requires type-constancy; (2) the AD-backed paths (<code>Flow(ocp)</code>, <code>Flow(ocp, DynClosedLoop)</code>) reject <code>Complex</code> and hand-built <code>Dual</code> for the same reason as <code>Flow(Hamiltonian)</code>. Two things are <strong>not</strong> broken, worth calling out explicitly: adding <code>constraint=</code>/<code>multiplier=</code> to a <code>DynClosedLoop</code> flow never changes which state types work (measured, not assumed), and <code>:total</code>/<code>:partial</code> agree exactly for a stationary feedback law. One asymmetry is new to these pages: <code>Flow(ocp, OpenLoop/ClosedLoop)</code> accepts a <code>ForwardDiff.Dual</code> state at a <em>point</em> call but not in a <em>trajectory</em> call (the objective computation is not <code>Dual</code>-transparent).</p></li><li><p><a href="./pseudo_hamiltonian"><code>Flow(h̃, law)</code></a> is the pseudo-Hamiltonian counterpart of <code>Flow(ocp, DynClosedLoop)</code>, but <strong>without an OCP</strong> — only <code>DynClosedLoop</code> is accepted (<code>OpenLoop</code>/<code>ClosedLoop</code> are rejected with <code>PreconditionError</code>, since a pseudo-Hamiltonian needs the costate). Because <code>PseudoHamiltonianSystem</code>/<code>Data.ComposedHamiltonian</code> wrap the user&#39;s <code>H̃</code> directly, with <strong>no OCP-derived fixed-size buffer</strong>, this constructor does <strong>not</strong> inherit <code>Flow(ocp, law)</code>&#39;s <code>Matrix</code>-family restriction — measured, not assumed: the full <code>Matrix</code>/<code>MMatrix</code>/<code>SMatrix</code> family works, on both <code>:total</code> and <code>:partial</code>. Its compatibility profile otherwise matches <code>Flow(Hamiltonian)</code> exactly: every <code>Real</code> container works, <code>Complex</code> fails (AD-backed), and a hand-built <code>Dual</code> collides with the flow&#39;s own internal AD.</p></li><li><p><a href="./controlled_vector_field"><code>Flow(fc, law)</code></a> is the controlled-vector-field counterpart of <code>Flow(h̃, law)</code> — only <code>OpenLoop</code>/<code>ClosedLoop</code> accepted (<code>DynClosedLoop</code> rejected, needs the costate). <code>Data.ControlledVectorField</code> has no in-place variant and, without an OCP, no fixed-size buffer either, so it builds the same plain out-of-place <code>VectorFieldSystem</code> as <code>Flow(VectorField)</code>. Measured: <strong>fully green</strong>, no unsupported combination at all — the most permissive of the four no-OCP/OCP &quot;control law&quot; pages, and a direct contrast with <code>Flow(ocp, law)</code>&#39;s <code>OpenLoop</code>/<code>ClosedLoop</code> path, whose <code>SVector</code>/<code>Matrix</code>/trajectory-<code>Dual</code> restrictions come entirely from the OCP-derived buffer and objective computation that don&#39;t exist here.</p></li><li><p><a href="./gpu">GPU</a> covers all constructors on NVIDIA/CUDA, sourced from a dated <a href="https://github.com/control-toolbox/CTFlows.jl/tree/main/probe/gpu" target="_blank" rel="noreferrer"><code>probe/gpu</code></a> run rather than build-executed (no device in the Documenter build). Headline finding: <strong><code>AutoMooncake</code> is the only AD backend that survives every measured device call shape</strong> — <code>AutoZygote</code> breaks once a call reduces over a device array or mutates one, <code>AutoEnzyme</code> breaks on GPU array reductions (<code>sum</code>/<code>mapreduce</code>) specifically, which real Hamiltonians always contain. AD-free flows (<code>VectorField</code>, <code>HamiltonianVectorField</code>, <code>ODEProblem</code>) need no keyword at all — just pass <code>CuArray</code>s.</p></li></ul><p>This completes the compatibility table for every <code>Flow</code> constructor, on both CPU and GPU.</p><h2 id="See-also" tabindex="-1">See also <a class="header-anchor" href="#See-also" aria-label="Permalink to &quot;See also {#See-also}&quot;">​</a></h2><ul><li><p><a href="./../flows/overview">Flows overview</a> — the data → systems → flows → trajectories pipeline.</p></li><li><p><a href="./../flows/building_a_flow">Building a flow</a> — the shortcut constructor and explicit pipeline.</p></li><li><p><a href="./../flows/integrating">Integrating</a> — call styles, variable parameters, and integrator options.</p></li></ul>',13)])])}const g=o(r,[["render",i]]);export{w as __pageData,g as default};
